/*!50003 CREATE*/ /*!50017 DEFINER=`pamahe`@`%`*/ /*!50003 TRIGGER `trg_parametros_tipo_no_desactivar` BEFORE UPDATE ON `parametros` FOR EACH ROW BEGIN
    IF OLD.categoria = 'TIPO_VEHICULO'
       AND OLD.activo = 1
       AND NEW.activo = 0
       AND EXISTS (
            SELECT 1
            FROM vehiculos v
            WHERE v.tipo_vehiculo = OLD.clave
       ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'No se puede desactivar un tipo de vehículo que está en uso.';
    END IF;
END */;;
DELIMITER ;
