  `creado_en` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `actualizado_en` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `marca` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `modelo` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipo_vehiculo` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo_vehiculo_categoria` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TIPO_VEHICULO',
  `anio` int NOT NULL,
  `matricula` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numero_chasis` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kilometraje` int DEFAULT NULL,
  `estado` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `costo_inicial` decimal(14,2) DEFAULT '0.00',
  `precio_venta_estimado` decimal(14,2) DEFAULT '0.00',
  `descripcion_publica` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `publicado` bit(1) NOT NULL DEFAULT b'0',
  `observaciones_internas` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_vehiculos_matricula` (`matricula`),
  UNIQUE KEY `uk_vehiculos_chasis` (`numero_chasis`),
  KEY `idx_vehiculos_estado_publicado` (`estado`,`publicado`),
  KEY `fk_vehiculos_tipo_parametro` (`tipo_vehiculo_categoria`,`tipo_vehiculo`),
  KEY `idx_vehiculos_stock_filtros` (`activo`,`estado`,`publicado`,`tipo_vehiculo`,`anio`,`precio_venta_estimado`),
  CONSTRAINT `fk_vehiculos_tipo_parametro` FOREIGN KEY (`tipo_vehiculo_categoria`, `tipo_vehiculo`) REFERENCES `parametros` (`categoria`, `clave`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `ck_vehiculos_anio` CHECK ((`anio` between 1900 and 2100)),
  CONSTRAINT `ck_vehiculos_costo_inicial` CHECK (((`costo_inicial` is null) or (`costo_inicial` >= 0))),
  CONSTRAINT `ck_vehiculos_kilometraje` CHECK (((`kilometraje` is null) or (`kilometraje` >= 0))),
  CONSTRAINT `ck_vehiculos_precio_estimado` CHECK (((`precio_venta_estimado` is null) or (`precio_venta_estimado` >= 0))),
  CONSTRAINT `ck_vehiculos_tipo_categoria` CHECK ((`tipo_vehiculo_categoria` = _utf8mb4'TIPO_VEHICULO'))
) ENGINE=InnoDB AUTO_INCREMENT=30121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
