/*!50003 CREATE*/ /*!50017 DEFINER=`pamahe`@`%`*/ /*!50003 TRIGGER `trg_vehiculos_tipo_activo_insert` BEFORE INSERT ON `vehiculos` FOR EACH ROW BEGIN
    IF NEW.tipo_vehiculo IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
            FROM parametros p
            WHERE p.categoria = 'TIPO_VEHICULO'
              AND p.clave = NEW.tipo_vehiculo
              AND p.activo = 1
       ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El tipo de vehículo debe existir y estar activo.';
    END IF;
END */;;
